import{_ as o,r as a,o as p,c as l,e as s,a as i,s as c}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Defining Navigation - October CMS - 4.x","titleTemplate":false,"description":"The menu items for managing the content in the admin panel.","frontmatter":{"subtitle":"The menu items for managing the content in the admin panel."},"headers":[{"level":2,"title":"Extra Navigation","slug":"extra-navigation","link":"#extra-navigation","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"4.x/cms/tailor/navigation.md","filePath":"4.x/cms/tailor/navigation.md"}'),r={name:"4.x/cms/tailor/navigation.md"};function u(d,n,g,k,h,m){const e=a("pre-heading"),t=a("post-heading");return p(),l("div",null,[s(e),n[0]||(n[0]=i("h1",null,"Defining Navigation",-1)),s(t),n[1]||(n[1]=c(`<p>In the backend area, entries will be listed under the Content menu item with globals listed under the Settings menu item (by default). You may control this behavior using the <strong>navigation</strong> property in the blueprint file. The following code will set an icon and specify the order of appearance.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">navigation</span><span class="token punctuation">:</span>
    <span class="token key atrule">icon</span><span class="token punctuation">:</span> icon<span class="token punctuation">-</span>pencil
    <span class="token key atrule">order</span><span class="token punctuation">:</span> <span class="token number">200</span>
</code></pre></div><p>The following properties are supported by the <code>navigation</code> and <code>primaryNavigation</code> definition.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>specifies the menu label localization string key, required.</td></tr><tr><td><strong>order</strong></td><td>a numerical weight when determining the display order.</td></tr><tr><td><strong>parent</strong></td><td>links the navigation item to a parent item using a blueprint handle.</td></tr><tr><td><strong>icon</strong></td><td>an icon name from the <a href="./../../element/available-icons.html">October CMS icon collection</a>, optional.</td></tr><tr><td><strong>iconSvg</strong></td><td>an SVG icon to be used in place of the standard icon, the SVG icon should be a rectangle and can support colors, optional.</td></tr></tbody></table></div><p>To place an item in the Settings area, set the <strong>parent</strong> to <code>settings</code>. The <strong>category</strong> definition can be a string or a settings constant reference, eg. <code>CATEGORY_COLLECTIONS</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">navigation</span><span class="token punctuation">:</span>
    <span class="token key atrule">parent</span><span class="token punctuation">:</span> settings
    <span class="token key atrule">category</span><span class="token punctuation">:</span> Collections
</code></pre></div><p>To place an item in the Content area, set the <strong>parent</strong> to <code>content</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">navigation</span><span class="token punctuation">:</span>
    <span class="token key atrule">parent</span><span class="token punctuation">:</span> content
</code></pre></div><p>To place the item as a primary navigation item. A <strong>primaryNavigation</strong> definition is needed.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">primaryNavigation</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Blog
    <span class="token key atrule">icon</span><span class="token punctuation">:</span> icon<span class="token punctuation">-</span>copy
    <span class="token key atrule">order</span><span class="token punctuation">:</span> <span class="token number">500</span>

<span class="token key atrule">navigation</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Main Menu Item
</code></pre></div><p>To place the item as a secondary navigation item. The <strong>parent</strong> property should specify the UUID or handle of a primary navigation item.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">navigation</span><span class="token punctuation">:</span>
    <span class="token key atrule">parent</span><span class="token punctuation">:</span> &lt;handle<span class="token punctuation">|</span>uuid<span class="token punctuation">&gt;</span>
</code></pre></div><p>To disable the secondary navigation, define the <strong>primaryNavigation</strong> for a single blueprint without it being a parent for any other blueprints.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">primaryNavigation</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Page
    <span class="token key atrule">icon</span><span class="token punctuation">:</span> icon<span class="token punctuation">-</span>magic
    <span class="token key atrule">order</span><span class="token punctuation">:</span> <span class="token number">500</span>
</code></pre></div><p>You may also completely disable the navigation by setting the <strong>navigation</strong> property to <code>false</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">navigation</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div><h2 id="extra-navigation"><a href="#extra-navigation" class="header-anchor">#</a> Extra Navigation</h2><p>Use the <code>extraNavigation</code> property to register custom navigation items to include with the blueprint. The value is an array matching the <code>sideMenu</code> definition found in the <a href="./../../extend/backend/navigation.html">backend navigation specification</a>. The following example includes two a section and divider using custom display types, the <code>order</code> property is used to align the items in the correct order.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">navigation</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Authors
    <span class="token key atrule">parent</span><span class="token punctuation">:</span> Blog\\Post
    <span class="token key atrule">icon</span><span class="token punctuation">:</span> icon<span class="token punctuation">-</span>user
    <span class="token key atrule">order</span><span class="token punctuation">:</span> <span class="token number">230</span>

<span class="token key atrule">extraNavigation</span><span class="token punctuation">:</span>
    <span class="token key atrule">_authors_section</span><span class="token punctuation">:</span>
        <span class="token key atrule">itemType</span><span class="token punctuation">:</span> section
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Authors
        <span class="token key atrule">order</span><span class="token punctuation">:</span> <span class="token number">210</span>

    <span class="token key atrule">_authors_ruler</span><span class="token punctuation">:</span>
        <span class="token key atrule">itemType</span><span class="token punctuation">:</span> ruler
        <span class="token key atrule">order</span><span class="token punctuation">:</span> <span class="token number">220</span>
</code></pre></div><p>You may also register links to <a href="./../../extend/system/controllers.html">controllers introduced by plugins</a> by specifying the <code>url</code> property. This property should be set to the controller URL, the following links to the <strong>acme/blog/posts</strong> controller.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">navigation</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Authors
    <span class="token comment"># ...</span>

<span class="token key atrule">extraNavigation</span><span class="token punctuation">:</span>
    <span class="token key atrule">testimonials</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Testimonials
        <span class="token key atrule">order</span><span class="token punctuation">:</span> <span class="token number">210</span>
        <span class="token key atrule">icon</span><span class="token punctuation">:</span> icon<span class="token punctuation">-</span>group
        <span class="token key atrule">url</span><span class="token punctuation">:</span> acme/blog/posts
</code></pre></div><p>To set the navigation context inside the controller, use the <code>setTailorContext</code> method on the <code>BackendMenu</code> facade. You may also specify the blueprint <code>uuid</code> with the <code>setTailorContextUuid</code> method. The method takes the <code>handle</code> or <code>uuid</code> of the blueprint (first argument), and the key used by the extra navigation item (second argument).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">BackendMenu</span><span class="token operator">::</span><span class="token function">setTailorContext</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Blog\\Post&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;testimonials&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">BackendMenu</span><span class="token operator">::</span><span class="token function">setTailorContextUuid</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;edcd102e-0525-4e4d-b07e-633ae6c18db6&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;testimonials&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../../extend/backend/navigation.html">Backend Navigation</a></li></ul></div>`,25))])}const b=o(r,[["render",u]]);export{v as __pageData,b as default};
